Write-Host "=== ESET SSL/TLS FILTER DRIVER DETECTION ==="; $drivers = Get-WmiObject Win32_SystemDriver | Where-Object { $_.Name -match "ekrn|eset|epfw|epfwwfp|ssl|tls|filter" }; if ($drivers) { $drivers | Select-Object Name,DisplayName,State,PathName,ServiceType | Format-Table -AutoSize } else { Write-Host "No ESET/SSL/TLS filter drivers found via WMI" }; Write-Host ""; Write-Host "=== ESET SERVICES ==="; Get-WmiObject Win32_Service | Where-Object { $_.Name -match "ekrn|eset|epfw|epfwwfp" } | Select-Object Name,State,StartMode,PathName | Format-Table -AutoSize; Write-Host ""; Write-Host "=== ALL LOADED DRIVERS (non-default) ==="; Get-WmiObject Win32_SystemDriver | Where-Object { $_.State -eq "Running" -and $_.Name -notmatch "TcpLink|lmhw|stornvme|fdc|Parport|Flpydisk|Parport|Beep|Nummm|Serial|SRSVEX|disk|ntfs|volmgr|volsnap|tcpip|afd|netbt|dhcpc|dns|iphlp|ndis|ndisau|IPSec|pacer|tdx|dxgkrnl|bthserv|Uv..|WdN.." } | Select-Object Name,DisplayName | Format-Table -AutoSize; Write-Host "---DONE---"
